CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('reviewer','publisher','admin','expert')), contexts text[] NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true, PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.whispers_access(ws text, needed text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND active AND role=needed AND ws=ANY(contexts)) $$;
REVOKE ALL ON FUNCTION public.whispers_access(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.whispers_access(text,text) TO authenticated;
CREATE TABLE public.whispers_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace text NOT NULL, body jsonb NOT NULL, code_hash text NOT NULL UNIQUE CHECK(code_hash ~ '^[0-9a-f]{64}$'), idempotency_key text NOT NULL UNIQUE, payload_hash text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days', revoked_at timestamptz, removal_requested_at timestamptz, version integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.whispers_reports TO authenticated;
GRANT ALL ON public.whispers_reports TO service_role;
ALTER TABLE public.whispers_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY reviewer_reports ON public.whispers_reports FOR SELECT TO authenticated USING(revoked_at IS NULL AND expires_at>now() AND public.whispers_access(workspace,'reviewer'));
CREATE TABLE public.whispers_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid REFERENCES public.whispers_reports(id) ON DELETE CASCADE, workspace text NOT NULL, kind text NOT NULL CHECK(kind IN ('message','note','evidence','risk','photo')), body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.whispers_records TO authenticated;
GRANT ALL ON public.whispers_records TO service_role;
ALTER TABLE public.whispers_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY reviewer_records ON public.whispers_records FOR SELECT TO authenticated USING(public.whispers_access(workspace,'reviewer') AND EXISTS(SELECT 1 FROM public.whispers_reports r WHERE r.id=report_id));
CREATE TABLE public.whispers_expert_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace text NOT NULL, report_ids uuid[] NOT NULL, packet jsonb NOT NULL, state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','closed')), interpretation text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.whispers_expert_requests TO authenticated;
GRANT ALL ON public.whispers_expert_requests TO service_role;
ALTER TABLE public.whispers_expert_requests ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.whispers_expert_assignments (request_id uuid REFERENCES public.whispers_expert_requests(id) ON DELETE CASCADE, expert_id uuid NOT NULL, PRIMARY KEY(request_id,expert_id));
GRANT SELECT ON public.whispers_expert_assignments TO authenticated;
GRANT ALL ON public.whispers_expert_assignments TO service_role;
ALTER TABLE public.whispers_expert_assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_assignment ON public.whispers_expert_assignments FOR SELECT TO authenticated USING(expert_id=auth.uid());
CREATE POLICY reviewer_requests ON public.whispers_expert_requests FOR SELECT TO authenticated USING(public.whispers_access(workspace,'reviewer'));
CREATE TABLE public.whispers_expert_responses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.whispers_expert_requests(id) ON DELETE CASCADE, expert_id uuid NOT NULL, choice text NOT NULL CHECK(choice IN ('consistent','conflicting','cannot_assess')), explanation text NOT NULL, source text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(request_id,expert_id));
GRANT SELECT ON public.whispers_expert_responses TO authenticated;
GRANT ALL ON public.whispers_expert_responses TO service_role;
ALTER TABLE public.whispers_expert_responses ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_expert_response ON public.whispers_expert_responses FOR SELECT TO authenticated USING(expert_id=auth.uid() OR EXISTS(SELECT 1 FROM public.whispers_expert_requests x WHERE x.id=request_id AND public.whispers_access(x.workspace,'reviewer')));
CREATE TABLE public.whispers_updates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace text NOT NULL, source_report_ids uuid[] NOT NULL DEFAULT '{}', body jsonb NOT NULL, state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','under_review','approved','published','withdrawn')), author_id uuid NOT NULL, disclosure_reviewer_id uuid, approver_id uuid, publisher_id uuid, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.whispers_updates TO authenticated;
GRANT ALL ON public.whispers_updates TO service_role;
ALTER TABLE public.whispers_updates ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_updates ON public.whispers_updates FOR SELECT TO authenticated USING(public.whispers_access(workspace,'reviewer') OR public.whispers_access(workspace,'publisher'));
CREATE VIEW public.whispers_public_updates AS SELECT id,body->>'title' AS title,body->>'summary' AS summary,body->>'known' AS known,body->>'uncertain' AS uncertain,body->'sources' AS sources,published_at,state='withdrawn' AS withdrawn FROM public.whispers_updates WHERE state IN ('published','withdrawn') AND published_at IS NOT NULL;
GRANT SELECT ON public.whispers_public_updates TO anon,authenticated;
CREATE TABLE public.whispers_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, target_id uuid, workspace text NOT NULL, outcome text NOT NULL DEFAULT 'ok', at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.whispers_audit TO authenticated;
GRANT ALL ON public.whispers_audit TO service_role;
ALTER TABLE public.whispers_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_audit ON public.whispers_audit FOR SELECT TO authenticated USING(public.whispers_access(workspace,'admin'));
CREATE TABLE public.whispers_release (id text PRIMARY KEY DEFAULT 'pilot', live_intake boolean NOT NULL DEFAULT false, operator_name text, operator_contact text, reviewed_at timestamptz);
GRANT SELECT ON public.whispers_release TO authenticated;
GRANT ALL ON public.whispers_release TO service_role;
ALTER TABLE public.whispers_release ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_release ON public.whispers_release FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND active));
CREATE FUNCTION public.whispers_update_report(p_id uuid,p_version integer,p_body jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.whispers_reports SET body=p_body,version=version+1 WHERE id=p_id AND version=p_version AND revoked_at IS NULL AND expires_at>now(); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.whispers_update_report(uuid,integer,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.whispers_update_report(uuid,integer,jsonb) TO service_role;
COMMENT ON TABLE public.whispers_release IS 'Real-source intake remains disabled until operator and independent release reviews are supplied.';